def split_for(index: int) -> str:
    if index and index % 19 == 0: return "cross_domain_holdout"
    if index and index % 17 == 0: return "sealed_test"
    if index and index % 13 == 0: return "validation"
    return "train"


def base(identifier: str, domain: str, subject: str, sources: list[str], split: str, kind: str, epistemic: str = "established") -> dict[str, Any]:
    return {
        "schema_version": 1, "record_id": identifier, "world_id": WORLD, "domain_id": domain,
        "subject_id": subject, "lanes": LANES, "record_kind": kind, "epistemic_class": epistemic,
        "coverage_axes": ["definitions_scope", "primitives_invariants", "mechanisms_causal_laws"],
        "source_ids": sorted(set(sources)), "scope": "HCI, linguistics, communication, and education foundation tranche",
        "limitations": ["Human evidence retains population, culture, language, disability, task, context, method, and uncertainty boundaries.", "No assessment score, neural signal, interface metric, or language variety defines a person's worth or complete ability."],
        "as_of": "2026-09-03", "version_boundary": "human-communication-learning-v0",
        "split_group": identifier, "split": split, "tags": ["foundation", domain],
    }


def context(prefix: str) -> tuple[str, list[str], str]:
    for item_prefix, domain, profiles, sources, _label, _statement in GROUPS:
        if item_prefix == prefix: return domain, sources, profiles[0][0]
    raise ValueError(prefix)


def build() -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []; index = 0
    for prefix, domain, profiles, sources, domain_label, domain_statement in GROUPS:
        records.append({**base(f"{prefix}.root", domain, profiles[0][0], sources, "train", "concept"), "label": domain_label, "statement": domain_statement, "aliases": [domain_label.lower()]})
        for subject, slug, label, definition, primitive_label, primitive_statement, mechanism_label, mechanism_statement, control_label, control_statement in profiles:
            for offset, (suffix, node_label, statement) in enumerate([("root", label, definition), ("primitive", primitive_label, primitive_statement), ("mechanism", mechanism_label, mechanism_statement)]):
                node_id = f"{prefix}.{slug}.{suffix}"
                records.append({**base(node_id, domain, subject, sources, "train" if suffix == "root" else split_for(index + offset), "concept", "interpretive" if prefix in {"hci", "ling"} else "established"), "label": node_label, "statement": statement, "aliases": [node_label.lower()]})
                target = f"{prefix}.root" if suffix == "root" else f"{prefix}.{slug}.root"
                rid = f"hcl.membership.{prefix}.{slug}.{suffix}"
                records.append({**base(rid, domain, subject, sources, split_for(index + offset + 4), "relation", "interpretive" if prefix in {"hci", "ling"} else "established"), "label": f"{node_label} world membership", "statement": f"{node_label} is a distinct component of {label} with explicit population, context, and evidence boundaries.", "aliases": [], "relation": {"source_node": node_id, "target_node": target, "kind": "part_of", "polarity": 1, "direction": "forward", "conditions": ["the declared population, language, task, and context apply"], "exceptions": []}, "coverage_axes": ["primitives_invariants", "within_domain_composition"]})
            cid = f"hcl.control.{prefix}.{slug}"
            records.append({**base(cid, domain, subject, [], ["train", "validation", "sealed_test", "cross_domain_holdout"][index % 4], "synthetic_control", "synthetic_control"), "label": control_label, "statement": control_statement, "aliases": [control_label.lower()], "synthetic": True, "coverage_axes": ["exceptions_boundaries", "errors_adversarial_misuse", "unknown_abstention"], "tags": ["negative-control", domain]})
            index += 1

    all_sources = sorted(set(HCI_SOURCES + LING_SOURCES + EDU_SOURCES)); splitter = RelationSplitter(
        [kind for _id, _s, _t, kind, _st in CROSS_RELATIONS],
        cross_plan=[
            source.split(".", 1)[0] != target.split(".", 1)[0]
            or identifier.startswith("bridge-")
            for identifier, source, target, _kind, _statement in CROSS_RELATIONS
        ],
    )
    for identifier, source, target, kind, statement in CROSS_RELATIONS:
        prefix = source.split(".", 1)[0]; domain, sources, subject = context(prefix); cross = prefix != target.split(".", 1)[0] or identifier.startswith("bridge-")
        split = splitter.split(kind)
        records.append({**base(f"hcl.relation.{identifier}", domain, subject, all_sources if cross else sources, split, "relation", "interpretive"), "label": identifier.replace("-", " "), "statement": statement, "aliases": [], "relation": {"source_node": source, "target_node": target, "kind": kind, "polarity": -1 if kind in {"inhibits", "prevents", "contradicts", "undercuts"} else 1, "direction": "forward", "conditions": ["population, language, task, context, and measurement are held fixed"], "exceptions": []}, "coverage_axes": ["mechanisms_causal_laws", "within_domain_composition", "cross_domain_composition"]})

    for example_index, (prefix, identifier, label, statement, subject) in enumerate(WORKED_EXAMPLES):
        domain, sources, _ = context(prefix); split = ["train", "validation", "sealed_test", "cross_domain_holdout"][example_index % 4]; node_id = f"hcl.example.{prefix}.{identifier}"
        records.append({**base(node_id, domain, subject, sources, split, "worked_example", "interpretive"), "label": label, "statement": statement, "aliases": [], "coverage_axes": ["applications_toolchains", "deductions_predictions_execution", "uncertainty_competing_hypotheses"], "tags": ["worked-example", domain]})
        records.append({**base(f"hcl.example-membership.{prefix}.{identifier}", domain, subject, sources, split, "relation", "interpretive"), "label": f"{label} membership", "statement": f"The {label.lower()} operationalizes one bounded human, language, or learning mechanism.", "aliases": [], "relation": {"source_node": node_id, "target_node": f"{prefix}.root", "kind": "part_of", "polarity": 1, "direction": "forward", "conditions": ["the example remains bounded"], "exceptions": []}, "coverage_axes": ["applications_toolchains", "within_domain_composition"]})
    return sorted(records, key=lambda row: row["record_id"])


def main() -> int:
    records = build(); OUTPUT.parent.mkdir(parents=True, exist_ok=True); OUTPUT.write_text("".join(json.dumps(row, ensure_ascii=False, sort_keys=True) + "\n" for row in records), encoding="utf-8")
    counts: dict[str, int] = {}; kinds: dict[str, int] = {}
    for row in records: counts[row["split"]] = counts.get(row["split"], 0) + 1; kinds[row["record_kind"]] = kinds.get(row["record_kind"], 0) + 1
    print(f"wrote {OUTPUT} with {len(records)} records: splits={dict(sorted(counts.items()))} kinds={dict(sorted(kinds.items()))}"); return 0


if __name__ == "__main__": raise SystemExit(main())
